function splitSheet(useDraft=false){
 if(!useDraft||!splitDraft){removedWorkout=null;const schedule=D.latest(state.trainingSchedules,now());splitDraft={effective:now(),days:D.clone(schedule?.days??[]).map(d=>({...d,exercises:d.exercises??[]}))};}
 modal('Edit Split',form('split',`${field('effective','Effective From',splitDraft.effective,{type:'date',required:true})}<details><summary>About Split Changes</summary><p class="caption">Earlier schedules and checked workouts keep their saved titles and exercise lists.</p></details>${button('Manage Exercise Library','split-library')}<div id="split-rows">${splitDraft.days.map(splitRow).join('')}</div>${button('Add Workout Day','add-workout')}${removedWorkout?button('Undo Remove Workout','undo-remove-workout'):''}`,'Save Split'));
}
function splitRow(day){
 const assigned=(day.exercises??[]).map(e=>({id:e.id,name:state.exercises.find(x=>x.id===e.id)?.name??e.name})),available=state.exercises.filter(e=>!e.archived&&!assigned.some(x=>x.id===e.id));
 return `<div class="split-row" data-workout="${h(day.id)}"><div class="form-grid">${select('weekday','Weekday',[[0,'Sunday'],[1,'Monday'],[2,'Tuesday'],[3,'Wednesday'],[4,'Thursday'],[5,'Friday'],[6,'Saturday']].map(([v,t])=>[String(v),t]),String(day.weekday))}${field('title','Workout Title',day.title,{type:'text',required:true})}</div><details class="assignment-editor" ${(day.open??assigned.length===0)?'open':''}><summary>Exercises (${assigned.length})</summary><ol class="assigned-list">${assigned.map((e,i)=>`<li data-assigned="${h(e.id)}"><span class="exercise-name">${h(e.name)}</span><div class="exercise-order">${i>0?button('↑','exercise-up',JSON.stringify([day.id,e.id]),'order-button',`Move ${e.name} up`):''}${i<assigned.length-1?button('↓','exercise-down',JSON.stringify([day.id,e.id]),'order-button',`Move ${e.name} down`):''}${button('Remove','remove-assigned',JSON.stringify([day.id,e.id]),'text-button',`Remove ${e.name} from workout`)}</div></li>`).join('')}</ol>${available.length?`${select('exercise-choice','Choose from Library',available.map(e=>[e.id,e.name]),available[0].id)}${button('Add Exercise','assign-exercise',day.id)}`:`<p class="caption">${state.exercises.some(e=>!e.archived)?'All active exercises are assigned.':'Add exercises in your library to choose them here.'}</p>`}</details>${button('Remove Workout','remove-workout',day.id)}</div>`;
}
function focusAssignment(workoutId,exerciseId){const target=dialog.querySelector(`[data-workout="${CSS.escape(workoutId)}"] [data-assigned="${CSS.escape(exerciseId)}"] .exercise-name`);if(target){target.tabIndex=-1;target.focus();}}
function exerciseLibrary(fromSplit=false){
 libraryReturn=fromSplit;exerciseEditing=null;
 modal('Exercise Library',`${libraryReturn?button('Back to Split','back-to-split'):''}<label>Search Exercises<input id="exercise-search" type="search" placeholder="Search your library" autocomplete="off"></label>${button('Add Exercise','new-exercise','','secondary')}<p class="caption">Your own exercise names. Assign them to workouts; completion is one checkmark per workout.</p>${libraryNotice?`<p role="status">Exercise archived. ${button('Undo','restore-exercise',libraryNotice)}</p>`:''}<div id="exercise-results"></div>`);exerciseResults();
}
function exerciseResults(){
 const query=$('#exercise-search').value.toLowerCase(),rows=state.exercises.filter(e=>e.name.toLowerCase().includes(query)).sort((a,b)=>a.name.localeCompare(b.name));
 const row=e=>`<div class="exercise-library-row"><strong>${h(e.name)}</strong><div class="entry-actions">${e.archived?button('Restore','restore-exercise',e.id):button('Rename','edit-exercise',e.id)+button('Archive','archive-exercise',e.id)}</div></div>`;
 $('#exercise-results').innerHTML=rows.filter(e=>!e.archived).map(row).join('')||'<p class="empty">No Exercises Found</p>';
 if(rows.some(e=>e.archived))$('#exercise-results').insertAdjacentHTML('beforeend',`<details><summary>Archived Exercises</summary>${rows.filter(e=>e.archived).map(row).join('')}</details>`);
}
function exerciseSheet(exerciseId=null){exerciseEditing=exerciseId;const exercise=state.exercises.find(e=>e.id===exerciseId);modal(exercise?'Rename Exercise':'Add Exercise',form('exercise',`${field('name','Exercise Name',exercise?.name??'',{type:'text',required:true})}<p class="caption">Checked workouts keep their saved exercise names. Renames appear in upcoming workouts and your library.</p>`,'Save Exercise')+button('Back to Library','back-to-library'));}
function settingsSheet(){
 const preferences=form('settings',`${field('timezone','Local Calendar Timezone',state.settings.timezone,{type:'text',required:true})}${select('weight-unit','Weight Entry Unit',['lb','kg'],state.settings.weightUnit)}<details><summary>Cardio Credit History</summary>${field('cardio-rollover-from','Cardio Rollover Starts',D.cardioRolloverStart(state),{type:'date',required:true})}<p class="caption">Choose a Sunday. Changing this date recalculates live cardio credit; saved check-ins stay unchanged.</p></details>`,'Save Settings');
 modal('Settings',`<section class="settings-data"><h3>Backup & Restore</h3><p class="caption">Last Backup: ${state.settings.lastExport?new Date(state.settings.lastExport).toLocaleString():'Never'}</p><div class="settings-actions">${button('Create Complete JSON Backup','backup','','primary')}${button('Restore JSON Backup','restore','','secondary')}</div><p class="caption">Records live on this phone. Keep a backup in Files; clearing website data can remove records.</p><details><summary>Other Exports</summary>${button('Export CSV Files','csv')}</details></section><details class="settings-options"><summary>Calendar & Units</summary>${preferences}</details><details class="settings-options"><summary>Archived Foods</summary>${state.foods.filter(f=>f.archived).map(f=>`<div class="row"><span>${h(f.name)}</span>${button('Restore','unarchive',f.id)}</div>`).join('')||'<p class="caption">No Archived Foods</p>'}</details><div class="settings-links">${button('Food Data Sources','sources')}${button('Installation Guide','install')}</div>`);
}
function download(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function backup(){await write(s=>{s.settings.lastExport=new Date().toISOString();s.settings.cardioRolloverFrom=D.cardioRolloverStart(s);});download(`road-to-the-stage-${now()}.json`,JSON.stringify(state,null,2));message('Complete backup created. Keep the downloaded file outside the app.');if(dialog.open)settingsSheet();}
function restoreSheet(){restoreCandidate=null;modal('Restore JSON Backup',`<p>Choose a backup to validate. Your current data stays unchanged until you review and confirm.</p><label>Backup File<input id="restore-file" type="file" accept=".json,application/json"></label><p class="form-error" role="alert" hidden></p><div id="restore-review"></div>`);}
function restoreReview(s){restoreCandidate=s;$('#restore-review').innerHTML=`<h3>Validated Backup</h3><p>${s.entries.length} Recorded Entries · ${s.plannedEntries.length} Planned Entries · ${s.foods.length} Foods · ${s.exercises.length} Library Exercises · ${s.weights.length} Weights · ${s.plans.length} Plans · ${s.checkins.length} Check-ins</p><p class="caption">All ${D.TABLES.length} record collections are included, including activity and historical snapshots.</p>${form('restore',`${select('mode','Restore Mode',[['merge','Merge — add missing records'],['replace','Replace — use this backup']], 'merge')}<p class="caption">Merge keeps current settings and blocks conflicts. Replace removes current records in favour of this backup. Export your current data first.</p>${check('confirm','I reviewed this choice and want to restore this backup.')}`,'Restore Backup')}`;}
function undoToast(table,records,credits=[]){clearTimeout(toastTimer);undo={table,records:D.clone(records),credits:D.clone(credits)};const t=$('#toast');t.hidden=false;t.innerHTML=`${table==='archive'?'Archived':'Deleted'} — ${button('Undo','undo')}<span class="sr-only">Available for at least ten seconds.</span>`;const expire=()=>{if(t.contains(document.activeElement)){toastTimer=setTimeout(expire,1000);return;}undo=null;t.hidden=true;};toastTimer=setTimeout(expire,10000);}
async function deleteRecord(table,recordId){
 const current=state[table].find(x=>x.id===recordId);D.assert(current,'Record no longer exists.');
 const credits=table==='cardioSessions'?state.cardioCredits.filter(c=>c.sessionId===recordId):[];
 await write(s=>{
  s[table]=s[table].filter(x=>x.id!==recordId);
  if(table==='cardioSessions')s.cardioCredits=s.cardioCredits.filter(x=>x.sessionId!==recordId);

 });close();undoToast(table,[current],credits);
}

async function undoDelete(){D.assert(undo,'Undo has expired.');const pending=D.clone(undo);await write(s=>{if(pending.table==='archive'){const food=s.foods.find(f=>f.id===pending.records[0].id);D.assert(food,'Food no longer exists.');food.archived=false;return;}for(const r of pending.records){D.assert(!(['entries','plannedEntries'].includes(pending.table)&&s[pending.table==='entries'?'plannedEntries':'entries'].some(x=>x.id===r.id)),'This item changed since deletion. Your newer record was kept.');D.assert(!s[pending.table].some(x=>x.id===r.id||(['weights'].includes(pending.table)&&x.date===r.date)),'A new record conflicts with Undo. Your newer record was kept.');s[pending.table].push(r);}for(const c of pending.credits)if(!s.cardioCredits.some(x=>x.id===c.id||x.sessionId===c.sessionId&&x.date===c.date))s.cardioCredits.push(c);if(pending.table==='cardioSessions')for(const r of pending.records)D.reconcileCredits(s,r.id);});undo=null;clearTimeout(toastTimer);message('Original record restored once.');}
